// === Tab: mySketch.js ===
/*  Genuary 2026 Day 9 Crazy Automaton

Game of Life shader with swapping buffers. My goal was to get something like the Reactive Rainbow linked below.
I have tried implementing GOL with buffers before, and always got stuck on the buffer swap. I don't have as nice
as version as Reactive Rainbow which is so cool, but with some help from chatGPT I do have have a basic color GOL
implementation (although at times it directly contradicted itself regarding how to swap buffers as in shaderToy). 

You can adjust neighborhood displacement to vary the render from standard GOL. You will probably kill all the cells, 
but you can add more with the mouse. I have added several image seed options. Use a mousePress to reset the animation with the
seed image.

References:
https://thecodingtrain.com/challenges/85-the-game-of-life
Matthew Wachter: Reactive Rainbow https://www.shadertoy.com/view/3ld3Dn

*/

let simShader, imgShader, colorShader;
let fbA, fbB;
let fbC1, fbC2;
let curC, nextC;

let curFB, nextFB;
let keys = {};
let seedImg; // seed image
let seeded = false;
let frame = 0;
let resetPulse = false;

let mouseDown = false;

function mousePressed() {
	mouseDown = true;
}

function mouseReleased() {
	mouseDown = false;
}

let params = {
	d: 2,
	seedChoice: "genuary",
	addSeed: false,
	reset: () => {
		resetPulse = true;
	}
}

function addGUIControls() {
	const guiContainer = createDiv();
	guiContainer.id("gui");
	guiContainer.parent(document.body);

	gui = new lil.GUI({
		container: document.getElementById("gui"),
	});

	gui.add(params, "seedChoice", ["squares", "genuary", "crazy"])
		.onChange((val) => addSeedImage(val));
	gui.add(params, "d", 1, 10, 1).name('Neighborhood displacement')
	gui.add(params, "addSeed").name('Add seed image')
	gui.add(params, 'reset').name('Reset GOL');

}

async function addSeedImage(choice) {
	switch (choice) {
		case "genuary":
			seedImg = await loadImage("https://openprocessing.org/sketch/2841920/files/genuary.jpg")
			break;
		case "crazy":
			seedImg = await loadImage("https://openprocessing.org/sketch/2841920/files/crazy.jpg");
			break;
		case "squares":
			seedImg = await loadImage("https://openprocessing.org/sketch/2841920/files/squares.jpg");
			break;
	}
}

async function setup() {
	const canvasSize = max(windowWidth, windowHeight);
	let canvas = createCanvas(canvasSize, canvasSize, WEBGL);
	canvas.position((windowWidth - width) / 2, (windowHeight - height) / 2);

	pixelDensity(1);
	noStroke();
	addGUIControls()

	addSeedImage(params.seedChoice)

	// Create ping-pong framebuffers
	fbA = createFramebuffer({
		width,
		height,
		format: FLOAT,
		textureFiltering: NEAREST
	});

	fbB = createFramebuffer({
		width,
		height,
		format: FLOAT,
		textureFiltering: NEAREST
	});

	fbC1 = createFramebuffer({
		width,
		height,
		format: FLOAT,
		textureFiltering: NEAREST
	});

	fbC2 = createFramebuffer({
		width,
		height,
		format: FLOAT,
		textureFiltering: NEAREST
	});

	curC = fbC1;
	nextC = fbC2;

	curFB = fbA;
	nextFB = fbB;

	// Shaders 
	simShader = createShader(simVert, simFrag)
	imgShader = createShader(imgVert, imgFrag);
	colorShader = createShader(colorVert, colorFrag);

}

function draw() {
	background(0);
	imageMode(CENTER)
	nextFB.begin();
	clear();
	push()
	translate(-width, -height)

	// GOL Simulation buffer
	shader(simShader);
	simShader.setUniform('u_mouseDown', mouseDown);
	simShader.setUniform('u_resolution', [width, height]);
	simShader.setUniform('u_img', seedImg);
	simShader.setUniform('addSeed', params.addSeed);
	simShader.setUniform('reset', resetPulse);
	simShader.setUniform('iMouse', [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (height - (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))))]);
	simShader.setUniform('iFrame', frameCount);
	simShader.setUniform('d', params.d);
	simShader.setUniform("u_tex", curFB);
	rect(-width, -height, width, height);
	nextFB.end();

	// Color buffer
	nextC.begin();
	shader(colorShader);
	colorShader.setUniform("u_gol", nextFB);
	colorShader.setUniform("u_prevColor", curC);
	colorShader.setUniform("u_resolution", [width, height]);
	colorShader.setUniform("iFrame", frame);

	rect(-width / 2, -height / 2, width, height);
	nextC.end();

	// Image buffer
	resetShader();
	shader(imgShader);

	imgShader.setUniform("u_bufferA", nextC);
	imgShader.setUniform("u_resolution", [width, height]);

	rect(-width / 2, -height / 2, width, height);

	// Swap buffers
	[curFB, nextFB] = [nextFB, curFB];
	[curC, nextC] = [nextC, curC];

	resetPulse = false; // one frame reset
	frame++;
}

function updateState() {
	if (params.addSeed) {
		params.reset = false;
	}
}

const mousePressVert = `#version 300 es 
in vec3 aPosition; void main() { gl_Position=vec4(aPosition*2.-1., 1.0); }
`;

const mousePressFrag = `#version 300 es
precision highp float;
out vec4 O;

uniform sampler2D u_img;
uniform vec2 u_resolution;
uniform int u_seed;

void main() {
    vec2 uv = gl_FragCoord.xy / u_resolution;
    vec3 c;
    if (u_seed == 1) {
        c = texture(u_img, uv).rgb;
        O = vec4(c, 1.0);
        return; // exit so nothing else overrides
    } else { O = vec4(0.0, 0.0, 0.0, 1.0);} 
}
`

const simVert = `#version 300 es 
in vec3 aPosition; void main() { gl_Position=vec4(aPosition*2.-1., 1.0); }
`;
const simFrag = `#version 300 es
precision highp float;
out vec4 O;

uniform sampler2D u_img;
uniform sampler2D u_tex;
uniform vec2 u_resolution;
uniform int u_mouseDown;
uniform bool addSeed;
uniform bool reset;
uniform vec2 iMouse;
uniform int iFrame;
uniform int d;
#define brushSize u_resolution.x/48.0

#define T(i,j) texture(u_tex, (uv + vec2(i,j)*vec2(1.0/u_resolution) )).r 
#define N(i,j) float(T(i,j) > 0.0)


//noise see https://www.shadertoy.com/view/ltB3zD
float snoise(in vec2 co){
    return fract(sin(dot(co.xy ,vec2(12.9898,78.233))) * 43758.5453)-.1;
}

void main()
{
    vec2 P  = gl_FragCoord.xy;
    vec2 uv = P / u_resolution;

    float v = texture(u_tex, uv).r;

    // Reset
    if (reset) {
        float alive = snoise(P) > 0.8 ? 1.0 : 0.0;
        O = vec4(vec3(alive), 1.0);
        return;
    }

    // Image Seed
    if (addSeed && u_mouseDown == 1) {
        vec2 st = vec2(uv.x, 1.0 - uv.y);
        float alive = texture(u_img, st).r;
        O = vec4(vec3(alive), 1.0);
        return;
    }

    // Brush
    if (u_mouseDown == 1 &&
        distance(P, iMouse) < brushSize &&
        !addSeed)
    {
        O = vec4(vec3(1.0), 1.0);
        return;
    }

    // Game of Life
	  if (iFrame > 4) {

        // float n =
        //       N(-1,-1) + N(-1, 0) + N(-1, 1)
        //     + N( 0,-1)             + N( 0, 1)
        //     + N( 1,-1) + N( 1, 0) + N( 1, 1);

				float n =
              N(-d,-d) + N(-d, 0) + N(-d, d)
            + N( 0,-d)             + N( 0,d)
            + N( d,-d) + N( d, 0) + N( d, d);

        // resurrect
        v += (1.0 - float(v > 0.0)) * float(n == 3.0);

        // survive
        v *= float(n == 2.0) + float(n == 3.0);

        // fade
        v -= float(v > 0.4) * 0.05;

        O = vec4(vec3(v), 1.0);
        return;
    }
	else
    {
      O = vec4(snoise(P) > 0.8 ? 1.0 : 0.0);
    }
}
`

const imgVert = `#version 300 es 
in vec3 aPosition; void main() { gl_Position=vec4(aPosition*2.-1., 1.0); }
`;

const imgFrag = `#version 300 es
precision highp float;

out vec4 O;

uniform sampler2D u_bufferA;
uniform vec2 u_resolution;

void main() {
  vec2 P  = gl_FragCoord.xy;
  vec2 uv = P / u_resolution;
  //vec2 uv = (gl_FragCoord.xy*2.0-u_resolution.xy) / u_resolution.y;
  //vec2 uv = gl_FragCoord.xy / u_resolution;
  vec3 col = texture(u_bufferA, uv).rgb;
  //float v = texture(u_bufferA, uv).r
  //O = vec4(vec3(v), 1.0);
  O = vec4(col, 1.0);
}
`;

const colorVert = `#version 300 es 
in vec3 aPosition; void main() { gl_Position=vec4(aPosition*2.-1., 1.0); }
`;

const colorFrag = `#version 300 es
precision highp float;

out vec4 O;

uniform sampler2D u_gol;
uniform sampler2D u_prevColor;
uniform vec2 u_resolution;
uniform int iFrame;

vec3 rgb2hsv(vec3 c) {
    float cmax = max(c.r, max(c.g, c.b));
    float cmin = min(c.r, min(c.g, c.b));
    float delta = cmax - cmin;

    float h = 0.0;
    if (delta > 0.00001) {
        if (cmax == c.r) {
            h = mod((c.g - c.b) / delta, 6.0);
        } else if (cmax == c.g) {
            h = (c.b - c.r) / delta + 2.0;
        } else { // cmax == c.b
            h = (c.r - c.g) / delta + 4.0;
        }
        h /= 6.0; // normalize to [0,1]
        if (h < 0.0) h += 1.0;
    }

    float s = (cmax == 0.0) ? 0.0 : delta / cmax;
    float v = cmax;
    return vec3(h, s, v);
}

// Convert HSV (0..1) to RGB (0..1)
vec3 hsv2rgb(vec3 c) {
    float h = c.x * 6.0;
    float s = c.y;
    float v = c.z;

    float i = floor(h);
    float f = h - i;

    float p = v * (1.0 - s);
    float q = v * (1.0 - s * f);
    float t = v * (1.0 - s * (1.0 - f));

    vec3 rgb;

    if (i == 0.0) rgb = vec3(v, t, p);
    else if (i == 1.0) rgb = vec3(q, v, p);
    else if (i == 2.0) rgb = vec3(p, v, t);
    else if (i == 3.0) rgb = vec3(p, q, v);
    else if (i == 4.0) rgb = vec3(t, p, v);
    else rgb = vec3(v, p, q);

    return rgb;
}

void main() {
  vec2 uv = gl_FragCoord.xy / u_resolution;

  float alive = texture(u_gol, uv).r;
  vec3 prev = texture(u_prevColor, uv).rgb;

vec3 colHSV = rgb2hsv(prev);   // convert previous color to HSV
if (alive > 0.0) {
    colHSV.x += 0.005;  
    colHSV.y = 1.0;            // full saturation
    colHSV.z = 1.0;            // full brightness
} else {
    colHSV.z *= 0.85;           // fade brightness when dead
}
vec3 col = hsv2rgb(colHSV);
col = clamp(col, 0.0, 1.0);
  O = vec4(col, 1.0);

}
`

